/**
 * Salesforce-pipeline connector — polls Salesforce REST for opportunities
 * updated since the last checkpoint and emits one event per opportunity
 * change. Used by the `sales` agent to keep its Opportunity entities in sync
 * with the source of truth.
 *
 * Auth: OAuth (Salesforce Connected App). Workers never see the token; the
 * gateway secret-proxy swaps the placeholder at egress.
 *
 * Auto-discovered by `lobu apply` because the filename ends in
 * `.connector.ts`.
 */

import {
  type ActionContext,
  type ActionResult,
  type ConnectorDefinition,
  ConnectorRuntime,
  type EventEnvelope,
  type SyncContext,
  type SyncResult,
} from "@lobu/connector-sdk";

interface PipelineConfig {
  instance_url: string;
  stages?: string[];
}

interface PipelineCheckpoint {
  last_modified: string;
}

interface SfOpportunity {
  Id: string;
  Name: string;
  StageName: string;
  Amount?: number;
  CloseDate?: string;
  AccountId?: string;
  LastModifiedDate: string;
}

const PAGE_SIZE = 200;

export default class SalesforcePipelineConnector extends ConnectorRuntime {
  readonly definition: ConnectorDefinition = {
    key: "salesforce-pipeline",
    name: "Salesforce pipeline",
    description: "Polls Salesforce REST for opportunity changes.",
    version: "1.0.0",
    authSchema: { methods: [{ type: "oauth", provider: "salesforce" }] },
    feeds: {
      opportunities: {
        key: "opportunities",
        name: "Opportunity changes",
        description:
          "Opportunities created or updated since the last sync cursor.",
        configSchema: {
          type: "object",
          required: ["instance_url"],
          properties: {
            instance_url: { type: "string", format: "uri" },
            stages: { type: "array", items: { type: "string" } },
          },
        },
        eventKinds: {
          opportunity_updated: {
            description: "An opportunity was created or modified.",
            metadataSchema: {
              type: "object",
              properties: {
                stage: { type: "string" },
                amount: { type: "number" },
                account_id: { type: "string" },
              },
            },
          },
        },
      },
    },
  };

  async sync(ctx: SyncContext): Promise<SyncResult> {
    const config = ctx.config as unknown as PipelineConfig;
    if (!config?.instance_url) {
      throw new Error("salesforce-pipeline: `instance_url` is required");
    }

    const checkpoint = (ctx.checkpoint as PipelineCheckpoint | null) ?? {
      last_modified: "2000-01-01T00:00:00Z",
    };
    const soql = this.buildSoql(checkpoint.last_modified, config.stages);
    const url = `${config.instance_url.replace(/\/$/, "")}/services/data/v60.0/query?q=${encodeURIComponent(soql)}`;

    const opportunities = await this.fetchOpportunities(url);
    const events: EventEnvelope[] = opportunities.map((opp) => ({
      origin_id: opp.Id,
      origin_type: "opportunity_updated",
      title: `Opportunity ${opp.Name} → ${opp.StageName}`,
      payload_text: `Amount: ${opp.Amount ?? "?"} · Closes ${opp.CloseDate ?? "?"}`,
      source_url: `${config.instance_url}/lightning/r/Opportunity/${opp.Id}/view`,
      occurred_at: new Date(opp.LastModifiedDate),
      metadata: {
        stage: opp.StageName,
        amount: opp.Amount,
        account_id: opp.AccountId,
      },
    }));

    const nextCursor =
      opportunities.length === 0
        ? checkpoint.last_modified
        : opportunities[opportunities.length - 1].LastModifiedDate;

    return {
      events,
      checkpoint: { last_modified: nextCursor } as unknown as Record<
        string,
        unknown
      >,
      metadata: { items_found: events.length },
    };
  }

  async execute(_ctx: ActionContext): Promise<ActionResult> {
    return { success: false, error: "Actions not supported" };
  }

  private buildSoql(since: string, stages?: string[]): string {
    const stageFilter =
      stages && stages.length > 0
        ? ` AND StageName IN (${stages.map((s) => `'${s}'`).join(",")})`
        : "";
    return `SELECT Id, Name, StageName, Amount, CloseDate, AccountId, LastModifiedDate FROM Opportunity WHERE LastModifiedDate > ${since}${stageFilter} ORDER BY LastModifiedDate ASC LIMIT ${PAGE_SIZE}`;
  }

  private async fetchOpportunities(url: string): Promise<SfOpportunity[]> {
    const response = await fetch(url, {
      headers: { Accept: "application/json" },
    });
    if (!response.ok) {
      throw new Error(`Salesforce ${response.status}: ${response.statusText}`);
    }
    const body = (await response.json()) as { records?: SfOpportunity[] };
    return body.records ?? [];
  }
}

/**
 * Shopify-orders connector — polls a Shopify shop's REST Admin API for new
 * or updated orders and emits one event per order transition (created,
 * paid, fulfilled, refunded). The `delivery` agent uses these to drive its
 * fulfilment-status entities and the at-risk-shipment dreaming watcher.
 *
 * Auth: Shopify private-app access token (header `X-Shopify-Access-Token`).
 * Workers never see the real token; the gateway secret-proxy swaps the
 * placeholder at egress.
 */

import {
  type ActionContext,
  type ActionResult,
  type ConnectorDefinition,
  ConnectorRuntime,
  type EventEnvelope,
  type SyncContext,
  type SyncResult,
} from "@lobu/connector-sdk";

interface ShopifyConfig {
  shop: string;
  status?: "open" | "closed" | "cancelled" | "any";
}

interface ShopifyCheckpoint {
  updated_at_min: string;
}

interface ShopifyOrder {
  id: number;
  name: string;
  email?: string;
  financial_status?: string;
  fulfillment_status?: string;
  total_price?: string;
  updated_at: string;
  created_at: string;
  customer?: { first_name?: string; last_name?: string };
}

const PAGE_SIZE = 100;
const API_VERSION = "2024-10";

export default class ShopifyOrdersConnector extends ConnectorRuntime {
  readonly definition: ConnectorDefinition = {
    key: "shopify-orders",
    name: "Shopify orders",
    description:
      "Polls Shopify Admin REST for new and updated orders to drive fulfilment workflows.",
    version: "1.0.0",
    authSchema: {
      methods: [
        {
          type: "env",
          fields: [
            { name: "access_token", description: "Shopify Admin API token" },
          ],
        },
      ],
    },
    feeds: {
      orders: {
        key: "orders",
        name: "Order updates",
        description: "Orders updated since the last cursor.",
        configSchema: {
          type: "object",
          required: ["shop"],
          properties: {
            shop: {
              type: "string",
              description: "Shopify shop subdomain (e.g. acme.myshopify.com)",
            },
            status: {
              type: "string",
              enum: ["open", "closed", "cancelled", "any"],
              default: "any",
            },
          },
        },
        eventKinds: {
          order_updated: {
            description: "A Shopify order was created or updated.",
            metadataSchema: {
              type: "object",
              properties: {
                financial_status: { type: "string" },
                fulfillment_status: { type: "string" },
                total_price: { type: "string" },
              },
            },
          },
        },
      },
    },
  };

  async sync(ctx: SyncContext): Promise<SyncResult> {
    const config = ctx.config as unknown as ShopifyConfig;
    if (!config?.shop) {
      throw new Error("shopify-orders: `shop` is required");
    }

    const checkpoint = (ctx.checkpoint as ShopifyCheckpoint | null) ?? {
      updated_at_min: "2000-01-01T00:00:00Z",
    };
    const status = config.status ?? "any";
    const url = `https://${config.shop}/admin/api/${API_VERSION}/orders.json?status=${status}&updated_at_min=${encodeURIComponent(checkpoint.updated_at_min)}&limit=${PAGE_SIZE}`;

    const orders = await this.fetchOrders(url);
    orders.sort(
      (a, b) =>
        new Date(a.updated_at).getTime() - new Date(b.updated_at).getTime()
    );

    const events: EventEnvelope[] = orders.map((order) => ({
      origin_id: `${order.id}:${order.updated_at}`,
      origin_type: "order_updated",
      title: `Order ${order.name} — ${order.fulfillment_status ?? "unfulfilled"}`,
      payload_text: `Financial: ${order.financial_status ?? "?"} · Total: ${order.total_price ?? "?"}`,
      author_name: order.customer
        ? `${order.customer.first_name ?? ""} ${order.customer.last_name ?? ""}`.trim()
        : undefined,
      source_url: `https://${config.shop}/admin/orders/${order.id}`,
      occurred_at: new Date(order.updated_at),
      metadata: {
        financial_status: order.financial_status,
        fulfillment_status: order.fulfillment_status,
        total_price: order.total_price,
      },
    }));

    const nextCursor =
      orders.length === 0
        ? checkpoint.updated_at_min
        : orders[orders.length - 1].updated_at;

    return {
      events,
      checkpoint: { updated_at_min: nextCursor } as unknown as Record<
        string,
        unknown
      >,
      metadata: { items_found: events.length },
    };
  }

  async execute(_ctx: ActionContext): Promise<ActionResult> {
    return { success: false, error: "Actions not supported" };
  }

  private async fetchOrders(url: string): Promise<ShopifyOrder[]> {
    const response = await fetch(url, {
      headers: { Accept: "application/json" },
    });
    if (!response.ok) {
      throw new Error(`Shopify ${response.status}: ${response.statusText}`);
    }
    const body = (await response.json()) as { orders?: ShopifyOrder[] };
    return body.orders ?? [];
  }
}

/**
 * Linear-cycles connector — polls Linear GraphQL for issues whose state
 * changed during the active cycle and emits one event per transition. The
 * `leadership` agent uses these to keep its Cycle and Initiative entities
 * in sync with engineering execution and to drive its nightly digest
 * dreaming watcher.
 *
 * Auth: Linear OAuth.
 */

import {
  type ActionContext,
  type ActionResult,
  type ConnectorDefinition,
  ConnectorRuntime,
  type EventEnvelope,
  type SyncContext,
  type SyncResult,
} from "@lobu/connector-sdk";

interface LinearConfig {
  team_id: string;
}

interface LinearCheckpoint {
  updated_at: string;
}

interface LinearIssue {
  id: string;
  identifier: string;
  title: string;
  url: string;
  updatedAt: string;
  state: { name: string; type: string };
  cycle?: { id: string; name?: string; number?: number };
  assignee?: { name: string };
}

const PAGE_SIZE = 100;
const ENDPOINT = "https://api.linear.app/graphql";

export default class LinearCyclesConnector extends ConnectorRuntime {
  readonly definition: ConnectorDefinition = {
    key: "linear-cycles",
    name: "Linear cycles",
    description:
      "Tracks issue state transitions inside the active Linear cycle for a team.",
    version: "1.0.0",
    authSchema: { methods: [{ type: "oauth", provider: "linear" }] },
    feeds: {
      cycle_issues: {
        key: "cycle_issues",
        name: "Cycle issue transitions",
        description:
          "Issues in the team's active cycle whose state changed since the last cursor.",
        configSchema: {
          type: "object",
          required: ["team_id"],
          properties: {
            team_id: { type: "string" },
          },
        },
        eventKinds: {
          issue_state_changed: {
            description: "A Linear issue moved to a new workflow state.",
            metadataSchema: {
              type: "object",
              properties: {
                state: { type: "string" },
                cycle_number: { type: "integer" },
                assignee: { type: "string" },
              },
            },
          },
        },
      },
    },
  };

  async sync(ctx: SyncContext): Promise<SyncResult> {
    const config = ctx.config as unknown as LinearConfig;
    if (!config?.team_id) {
      throw new Error("linear-cycles: `team_id` is required");
    }

    const checkpoint = (ctx.checkpoint as LinearCheckpoint | null) ?? {
      updated_at: "2000-01-01T00:00:00Z",
    };

    const issues = await this.fetchIssues(
      config.team_id,
      checkpoint.updated_at
    );
    const events: EventEnvelope[] = issues.map((issue) => ({
      origin_id: `${issue.id}:${issue.state.name}:${issue.updatedAt}`,
      origin_type: "issue_state_changed",
      title: `${issue.identifier} ${issue.title} → ${issue.state.name}`,
      author_name: issue.assignee?.name,
      source_url: issue.url,
      occurred_at: new Date(issue.updatedAt),
      metadata: {
        state: issue.state.name,
        cycle_number: issue.cycle?.number,
        assignee: issue.assignee?.name,
      },
    }));

    const nextCursor =
      issues.length === 0
        ? checkpoint.updated_at
        : issues[issues.length - 1].updatedAt;

    return {
      events,
      checkpoint: { updated_at: nextCursor } as unknown as Record<
        string,
        unknown
      >,
      metadata: { items_found: events.length },
    };
  }

  async execute(_ctx: ActionContext): Promise<ActionResult> {
    return { success: false, error: "Actions not supported" };
  }

  private async fetchIssues(
    teamId: string,
    updatedAfter: string
  ): Promise<LinearIssue[]> {
    const query = `query Cycle($teamId: ID!, $after: DateTimeOrDuration!, $first: Int!) {
      issues(
        first: $first,
        filter: { team: { id: { eq: $teamId } }, updatedAt: { gt: $after }, cycle: { isActive: { eq: true } } },
        orderBy: updatedAt
      ) {
        nodes {
          id identifier title url updatedAt
          state { name type }
          cycle { id name number }
          assignee { name }
        }
      }
    }`;
    const response = await fetch(ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        query,
        variables: { teamId, after: updatedAfter, first: PAGE_SIZE },
      }),
    });
    if (!response.ok) {
      throw new Error(`Linear ${response.status}: ${response.statusText}`);
    }
    const body = (await response.json()) as {
      data?: { issues?: { nodes?: LinearIssue[] } };
    };
    return body.data?.issues?.nodes ?? [];
  }
}

